package ama.storage;
import java.sql.*;import java.lang.reflect.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import javax.sql.DataSource;import static org.junit.jupiter.api.Assertions.*;
/** Actual content writer attempts growth after worker metadata locks, always rolls back. */
final class Task11Fix02ContentRace {
 final java.util.List<String> steps=new CopyOnWriteArrayList<>();final AtomicReference<Connection> writerConnection=new AtomicReference<>();DataSource raw;String task,original;boolean armed,hit;final CountDownLatch entered=new CountDownLatch(1),finished=new CountDownLatch(1);final AtomicReference<Throwable> failure=new AtomicReference<>();volatile boolean blocked,updated,rolledBack;Thread writer;
 void arm(String task,String original){this.task=task;this.original=original;armed=true;}
 void finish()throws Exception{if(writer==null)return;if(!finished.await(6,TimeUnit.SECONDS)){var active=writerConnection.get();if(active!=null)active.abort(Runnable::run);writer.interrupt();}writer.join(2000);assertFalse(writer.isAlive(),"Writer must exit before test can progress");steps.add("writer-exited");}
 void await()throws Exception{finish();assertTrue(finished.getCount()==0);assertNull(failure.get(),failure.get()==null?"":failure.get().getClass().getName());assertTrue(hit&&blocked&&updated&&rolledBack);writer.join(1000);assertFalse(writer.isAlive());}
 DataSource wrap(DataSource actual){raw=actual;return (DataSource)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{DataSource.class},(p,m,a)->{Object value=Task11ReplacementRollbackIT.invoke(actual,m,a);if(!(value instanceof Connection c))return value;return Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{Object result=Task11ReplacementRollbackIT.invoke(c,cm,ca);if(!(result instanceof PreparedStatement statement)||ca==null||ca.length==0||!(ca[0] instanceof String sql))return result;return Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{PreparedStatement.class},(sp,sm,sa)->{
   if(armed&&!hit&&sm.getName().equals("executeQuery")&&sql.startsWith("SELECT request_manifest FROM publication_submission")){hit=true;assertFalse(c.getAutoCommit());assertTrue(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());Connection physical=c.unwrap(Connection.class);
    writer=new Thread(()->{try(var other=raw.getConnection()){assertNotSame(physical,other.unwrap(Connection.class));writerConnection.set(other);other.setAutoCommit(false);steps.add("writer-connected-separate-physical");try{
     try(var setting=other.createStatement()){setting.execute("SET SESSION innodb_lock_wait_timeout=1");}
     try(var update=other.prepareStatement("UPDATE publication_submission SET request_manifest=? WHERE task_id=?")){update.setQueryTimeout(4);update.setString(1,original+" ".repeat(4096));update.setString(2,task);var timeout=assertThrows(SQLException.class,update::executeUpdate);assertEquals(1205,timeout.getErrorCode(),"Actual MySQL lock wait timeout required while reader retains its row lock");blocked=true;steps.add("first-update-actual-mysql1205");}
     other.rollback();steps.add("first-transaction-rollback");entered.countDown();try(var setting=other.createStatement()){setting.execute("SET SESSION innodb_lock_wait_timeout=3");}
     try(var update=other.prepareStatement("UPDATE publication_submission SET request_manifest=? WHERE task_id=?")){update.setQueryTimeout(5);update.setString(1,original+" ".repeat(4096));update.setString(2,task);steps.add("second-update-started");assertEquals(1,update.executeUpdate());updated=true;steps.add("second-update-succeeded-after-reader-release");}
    }finally{other.rollback();rolledBack=true;steps.add("second-transaction-rollback");}}catch(Throwable thrown){failure.set(thrown);steps.add("writer-exception-"+thrown.getClass().getSimpleName());entered.countDown();}finally{finished.countDown();}},"FIX02_CONTENT_WRITER");writer.start();assertTrue(entered.await(3,TimeUnit.SECONDS));assertNull(failure.get());assertTrue(blocked,"MySQL1205 proves actual competing UPDATE waited on retained reader lock");
   }
   return Task11ReplacementRollbackIT.invoke(statement,sm,sa);
  });});});}
}
